template <std::size_t Slots, std::size_t MaxThreads> class MpmcQueue {
    static_assert(Slots >= 2 && Slots < std::numeric_limits<std::size_t>::max() / 2 &&
                  MaxThreads > 0);
    // ================= 严格无锁与安全回收辅助：开始 =================
    enum class State : std::uint8_t { Free, InUse, Retired, Scanning };
    struct Node {
        std::atomic<Node *> next{nullptr};
        std::atomic<State> state{State::Free};
        int value = 0;
    };
    struct Hazard {
        std::atomic<bool> used{false};
        std::array<std::atomic<Node *>, 2> pointers{};
    };
    static_assert(std::atomic<Node *>::is_always_lock_free &&
                  std::atomic<State>::is_always_lock_free);
    static_assert(std::atomic<bool>::is_always_lock_free &&
                  std::atomic<std::size_t>::is_always_lock_free);
    std::array<Node, Slots> nodes{};
    std::array<Hazard, MaxThreads> hazards{};
    std::atomic<std::size_t> allocationCursor{0};
    std::atomic<Node *> head{&nodes[0]}, tail{&nodes[0]};
    void clear(std::size_t slot) noexcept {
        for (auto &pointer : hazards[slot].pointers)
            pointer.store(nullptr);
    }
    Node *protect(std::atomic<Node *> &source, std::size_t slot, std::size_t index) noexcept {
        Node *observed;
        do {
            observed = source.load();
            hazards[slot].pointers[index].store(observed);
        } while (source.load() != observed);
        return observed;
    }
    bool protectedNow(Node *node) const noexcept {
        for (const auto &record : hazards)
            for (const auto &pointer : record.pointers)
                if (pointer.load() == node)
                    return true;
        return false;
    }
    Node *acquireNode() noexcept {
        const auto start = allocationCursor.fetch_add(1) % Slots;
        for (std::size_t step = 0; step < Slots; ++step) {
            auto &node = nodes[(start + step) % Slots];
            auto expected = State::Free;
            if (node.state.compare_exchange_strong(expected, State::InUse))
                return &node;
            expected = State::Retired;
            // 先独占检查权，避免扫描期间 Retired -> InUse -> Retired 的状态 ABA。
            if (node.state.compare_exchange_strong(expected, State::Scanning)) {
                if (protectedNow(&node)) {
                    node.state.store(State::Retired);
                    continue;
                }
                node.state.store(State::InUse);
                return &node;
            }
        }
        return nullptr; // 有界资源当前不可用，允许重试；不声称逻辑队列恰好已满。
    }
    friend struct QueueProbe; // 仅测试用来保留一个 hazard，模拟线程被抢占。
  public:
    class Token {
        friend class MpmcQueue;
        friend struct QueueProbe;
        MpmcQueue *owner;
        std::size_t slot;
        Token(MpmcQueue *queue, std::size_t index) : owner(queue), slot(index) {}

      public:
        Token(const Token &) = delete;
        Token &operator=(const Token &) = delete;
        Token(Token &&other) noexcept
            : owner(std::exchange(other.owner, nullptr)), slot(other.slot) {}
        Token &operator=(Token &&) = delete;
        ~Token() {
            if (owner) {
                owner->clear(slot);
                owner->hazards[slot].used.store(false);
            }
        }
    };
    MpmcQueue() { nodes[0].state.store(State::InUse); }
    MpmcQueue(const MpmcQueue &) = delete;
    MpmcQueue &operator=(const MpmcQueue &) = delete;
    ~MpmcQueue() {
        for (const auto &hazard : hazards)
            assert(!hazard.used.load());
    }
    Token registerThread() {
        for (std::size_t i = 0; i < MaxThreads; ++i) {
            bool expected = false;
            if (hazards[i].used.compare_exchange_strong(expected, true))
                return Token(this, i);
        }
        throw std::runtime_error("queue thread slots exhausted");
    }
    // ================= 严格无锁与安全回收辅助：结束 =================
    // ================= 面试核心：链接节点、帮助推进尾、CAS 摘头 =================
    bool tryPush(Token &token, int value) noexcept {
        if (token.owner != this)
            return false;
        auto *node = acquireNode();
        if (!node)
            return false;
        node->value = value;
        node->next.store(nullptr);
        while (true) {
            auto *last = protect(tail, token.slot, 0);
            auto *next = last->next.load();
            if (last != tail.load())
                continue;
            if (next) {
                tail.compare_exchange_strong(last, next);
                continue;
            }
            if (last->next.compare_exchange_strong(next, node)) {
                tail.compare_exchange_strong(last, node);
                clear(token.slot);
                return true;
            }
        }
    }
    bool tryPop(Token &token, int &value) noexcept {
        if (token.owner != this)
            return false;
        while (true) {
            auto *first = protect(head, token.slot, 0);
            auto *next = first->next.load();
            hazards[token.slot].pointers[1].store(next);
            if (first != head.load() || next != first->next.load())
                continue;
            if (!next) {
                clear(token.slot);
                return false;
            }
            auto *last = tail.load();
            if (first == last) {
                tail.compare_exchange_strong(last, next);
                continue;
            }
            int result = next->value;
            if (head.compare_exchange_strong(first, next)) {
                value = result;
                first->state.store(State::Retired);
                clear(token.slot);
                return true;
            }
        }
    }
